/**
 * Preview sessions: one per right-click, held in memory only, never persisted.
 * Opening the same folder twice gives two independent sessions. The docs sidebar
 * keeps and reuses one session per workspace folder instead (ADR 0008).
 */
import { renderTreeList } from './pages';
import { fileUrl } from './routes';
import { buildTree, type TreeNode } from './tree';

/** How a folder session found its files. */
export type Discovery = 'git' | 'walk';

export interface Session {
  /** 32 random bytes, base64url. Generated by the adapter. */
  readonly token: string;
  readonly mode: 'folder' | 'file';
  /** Real path of the folder that bounds what may be served. */
  readonly scopeRoot: string;
  /** Display name of the scope root, the first breadcrumb. */
  readonly scopeName: string;
  /** Scope-relative path of the start page, or `undefined` for the generated index. */
  readonly entry: string | undefined;
  /** Folder mode: the discovered Markdown files and their tree. File mode: none. */
  files: readonly string[] | undefined;
  tree: readonly TreeNode[] | undefined;
  /** The tree's markup, built once per discovery (`renderTreeList`). */
  treeHtml: string | undefined;
  discovery: Discovery | undefined;
  /** True when the walk stopped at its entry cap. */
  truncated: boolean;
  /** A docs-sidebar session that also lists ignored Markdown; a reload rediscovers the same way. */
  readonly includeIgnored?: boolean;
  /**
   * True right after discovery. The first load of the entry page then uses that
   * result instead of scanning again; later loads (a reload) rebuild the tree.
   */
  fresh: boolean;
}

/** What a folder session needs from discovery. */
export interface DiscoveryResult {
  readonly files: readonly string[];
  readonly discovery: Discovery;
  readonly truncated: boolean;
}

/** `README.md`, `readme.markdown`, … at the root of the file list, if any. */
export function findRootReadme(files: readonly string[]): string | undefined {
  return files.find((file) => /^readme\.(md|markdown)$/i.test(file));
}

/** Applies a discovery result to a folder session (also used to rebuild on reload). */
export function applyDiscovery(session: Session, result: DiscoveryResult): void {
  session.files = result.files;
  session.tree = buildTree(result.files);
  session.treeHtml = renderTreeList(session.tree, (path) => fileUrl(session.token, path));
  session.discovery = result.discovery;
  session.truncated = result.truncated;
  session.fresh = true;
}

/**
 * The in-memory session registry. Token comparison is injected so the adapter can
 * use a constant-time comparison (`timingSafeEqual`); the core stays free of Node.
 */
export class SessionStore {
  private readonly sessions: Session[] = [];

  constructor(private readonly equals: (a: string, b: string) => boolean) {}

  add(session: Session): void {
    this.sessions.push(session);
  }

  /** Finds a session by token, comparing against every session (no early exit). */
  find(token: string): Session | undefined {
    let found: Session | undefined;
    for (const session of this.sessions) {
      if (this.equals(session.token, token) && found === undefined) {
        found = session;
      }
    }
    return found;
  }

  clear(): void {
    this.sessions.length = 0;
  }

  get size(): number {
    return this.sessions.length;
  }
}
